+        AgentEvent::RunStopped { reason, usage } => {
+            let mut total = parent_usage;
+            total.add(usage);
+            record_usage(&total);
+            Some(AgentEvent::RunStopped {
+                reason,
+                usage: total,
+            })
+        }
         other => Some(other),
     }
 }
